{
  "action": "question",
  "question_count": 2,
  "is_atomic": false,
  "atomic_questions": [
    "What is the objective of this production plan — should I maximize total profit (unit price minus raw material cost, minus the equipment operating costs)?",
    "Is the \"Operating Costs at Full Capacity\" a fixed cost incurred whenever the machine is used at all, or a cost proportional to the fraction of its effective hours actually used?"
  ],
  "rationale": "The response contains two semantically independent questions: one asking for the optimization objective (maximize profit) and another asking for the cost structure of operating costs (fixed vs. proportional). A user could confirm the objective without specifying the cost structure, or vice versa."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is there a demand limit (maximum number of units) for each product, or can I produce unlimited quantities of each product as long as the machine-hour capacities are respected?"
  ],
  "rationale": "The response asks a single clarification question regarding whether demand is capped or unlimited, which constitutes one independent semantic request."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "For each finished unit of a product, does it require exactly one unit of procedure A processing and exactly one unit of procedure B processing (i.e., the A and B processing amounts for a product are equal), or can the amounts differ?"
  ],
  "rationale": "The response contains a single clarification question asking for a policy choice regarding the relationship between processing amounts for procedures A and B."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "If a machine is used only partially (less than its full effective hours), do you still pay the full fixed operating cost, or is the cost prorated by the fraction of hours actually used?"
  ],
  "rationale": "The response asks for a single policy choice regarding cost allocation for partial machine usage."
}

